const CONFIG = {
  ollamaUrl: 'http://ollama:11434',
  embedModel: 'bge-m3',
  chunkSize: 1200,
  chunkOverlap: 200,
};

const req = $input.first();
const body = req.json.body || {};
const items = [];

for (const [key, bin] of Object.entries(req.binary || {})) {
  const fileName = bin.fileName || key;
  items.push({ json: { source: body.source || fileName, fileName, config: CONFIG }, binary: { data: bin } });
}
if (body.text) {
  const source = body.source || 'inline-text';
  items.push({
    json: { source, fileName: source, config: CONFIG },
    binary: {
      data: {
        data: Buffer.from(String(body.text), 'utf8').toString('base64'),
        mimeType: 'text/plain',
        fileName: source + '.txt',
      },
    },
  });
}
if (!items.length) throw new Error('Send at least one file or a "text" field');
return items;

function htmlToText(html) {
  return String(html)
    .replace(/<head[\s\S]*?<\/head>/gi, '')
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
    .replace(/<br\s*\/?>|<\/(p|div|h[1-6]|li|tr)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function chunkText(text, size, overlap) {
  const out = [];
  let start = 0;
  while (start < text.length) {
    let end = Math.min(start + size, text.length);
    if (end < text.length) {
      const brk = Math.max(text.lastIndexOf('\n', end), text.lastIndexOf('. ', end));
      if (brk > start + size * 0.5) end = brk + 1;
    }
    const piece = text.slice(start, end).trim();
    if (piece) out.push(piece);
    if (end >= text.length) break;
    start = Math.max(end - overlap, start + 1);
  }
  return out;
}

// Tika returns XHTML; PDFs come back with one <div class="page"> per page.
function splitPages(html) {
  const parts = String(html).split(/<div class="page">/i);
  if (parts.length > 1) return parts.slice(1).map((p, i) => ({ page: i + 1, text: htmlToText(p) }));
  return [{ page: null, text: htmlToText(html) }];
}

const prepared = $('Prepare upload').all();
const cfg = prepared[0].json.config;

const chunks = [];
$input.all().forEach((item, i) => {
  const source = prepared[i].json.source;
  let chunkIndex = 0;
  for (const { page, text } of splitPages(item.json.data || '')) {
    for (const piece of chunkText(text, cfg.chunkSize, cfg.chunkOverlap)) {
      chunks.push({ source, page, chunkIndex: chunkIndex++, text: piece });
    }
  }
});
if (!chunks.length) throw new Error('No text could be extracted (scanned file without OCR?)');
return [{ json: { chunks, embedModel: cfg.embedModel } }];

// Re-ingesting a source replaces its previous chunks (single statement).
const chunks = $('Split into chunks').first().json.chunks;
const vecs = $input.first().json.embeddings;
const esc = s => "'" + String(s).replace(/\u0000/g, '').replace(/'/g, "''") + "'";

const sources = [...new Set(chunks.map(c => c.source))];
const values = chunks.map((c, i) =>
  `(${esc(c.source)}, ${Number.isInteger(c.page) ? c.page : 'NULL'}, ${c.chunkIndex}, ${esc(c.text)}, '[${vecs[i].join(',')}]'::vector)`
);

const sql = `WITH del AS (
  DELETE FROM kb_chunks WHERE source IN (${sources.map(esc).join(', ')}) RETURNING 1
), ins AS (
  INSERT INTO kb_chunks (source, page, chunk_index, content, embedding) VALUES
  ${values.join(',\n  ')}
  RETURNING 1
)
SELECT (SELECT count(*) FROM del) AS deleted, (SELECT count(*) FROM ins) AS inserted;`;

return [{ json: { sql, sources } }];
